(() => {
'use strict';
const wf=()=>window.KsppsWorkflow,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={reports:[],loaded:false,loading:false,error:'',filter:'',busy:false};let requestId='';
const names={utilization:'Penggunaan Dana',financial:'Laporan Keuangan'};
const manager=()=>location.pathname.endsWith('petugas.html')&&wf()?.getStaff()?.role==='manager'&&wf()?.getStaff()?.accountRole==='manager';
function cards(){if(state.error)return `<p class="form-error" role="alert">${esc(state.error)}</p>`;if(!state.loaded)return '<p role="status">Memuat laporan…</p>';const items=state.reports.filter(r=>!state.filter||r.category===state.filter);return items.length?`<div class="offer-grid">${items.map(r=>`<article class="offer-card"><span class="badge gray">${names[r.category]}</span><h3>${esc(r.title)}</h3><p class="small muted">Periode ${esc(r.period)}${r.projectCode?' · <span class="offer-code">'+esc(r.projectCode)+'</span>':''}</p><p class="field-hint">Diunggah ${new Date(r.createdAt).toLocaleDateString('id-ID',{timeZone:'Asia/Makassar'})} oleh ${esc(r.uploadedBy)}</p><div class="wf-actions"><a class="btn secondary small-btn" href="${r.url}" target="_blank" rel="noopener">Lihat PDF</a><a class="btn small-btn" href="${r.url}?download=1">Unduh</a></div></article>`).join('')}</div>`:'<div class="empty-state">Belum ada laporan yang diterbitkan.</div>';}
function page(){return `<div class="page-heading"><div><h1>Laporan Koperasi</h1><p class="subtext">Penggunaan dana penyertaan modal dan laporan keuangan.</p></div>${manager()?'<button class="btn" data-report-action="upload">+ Unggah laporan</button>':''}</div><section class="panel"><div class="toolbar"><label class="form-field"><span>Jenis laporan</span><select class="filter-select" id="report-filter"><option value="">Semua laporan</option>${Object.entries(names).map(([v,n])=>`<option value="${v}" ${state.filter===v?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn secondary small-btn" data-report-action="refresh">Perbarui</button></div><div id="report-list">${cards()}</div></section>`;}
async function load(){if(state.loading)return;state.loading=true;state.error='';try{state.reports=(await wf().api('/reports')).reports;state.loaded=true;}catch(e){state.error=e.message;}finally{state.loading=false;const el=$('#report-list');if(el)el.innerHTML=cards();}}
function mount(){if($('#report-list')&&!state.loaded&&!state.loading&&!state.error)void load();}
function upload(){if(!manager())return;requestId=crypto.randomUUID();const modal=$('#portal-dialog');if(modal.open)modal.close();$('#dialog-content').innerHTML=`<div class="dialog-inner"><div class="dialog-head"><h2 id="dialog-title">Unggah laporan</h2><button class="icon-btn" data-report-action="close" aria-label="Tutup">×</button></div><form id="report-upload"><label class="form-field"><span>Jenis laporan *</span><select name="category" id="report-category" required><option value="financial">Laporan Keuangan</option><option value="utilization">Penggunaan Dana Penyertaan Modal</option></select></label><label class="form-field"><span>Judul laporan *</span><input name="title" maxlength="120" required placeholder="Laporan Keuangan September 2026"></label><label class="form-field"><span>Periode *</span><input name="period" type="month" required></label><label class="form-field" id="report-project-field" hidden><span>Kode project *</span><input name="projectCode" maxlength="60" placeholder="MRBH-2026-09-01"></label><label class="form-field"><span>File laporan PDF *</span><input name="file" type="file" accept=".pdf,application/pdf" required><small>PDF · Maksimal 10 MB</small></label><label class="check"><input name="confirm" type="checkbox" required>Laporan sudah diperiksa dan boleh dibaca anggota koperasi.</label><p id="report-error" class="form-error" role="alert" hidden></p><div class="form-actions"><button type="button" class="btn secondary" data-report-action="close">Batal</button><button type="submit" class="btn">Terbitkan laporan</button></div></form></div>`;modal.showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-report-action]');if(!b||state.busy)return;const a=b.dataset.reportAction;if(a==='upload')upload();if(a==='close')$('#portal-dialog').close();if(a==='refresh'){state.loaded=false;void load();}});
document.addEventListener('change',e=>{if(e.target.id==='report-filter'){state.filter=e.target.value;$('#report-list').innerHTML=cards();}if(e.target.id==='report-category'){const need=e.target.value==='utilization',label=$('#report-project-field');label.hidden=!need;label.querySelector('input').required=need;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='report-upload')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target;if(state.busy||!form.reportValidity())return;const data=new FormData(form);if(data.get('file').size>10*1024*1024){$('#report-error').hidden=false;$('#report-error').textContent='Ukuran laporan maksimal 10 MB.';return;}data.set('id',requestId);data.set('confirm',String(data.get('confirm')==='on'));state.busy=true;form.querySelectorAll('input,select,button').forEach(x=>x.disabled=true);try{const {report}=await wf().api('/reports',{method:'POST',body:data});state.reports=[report,...state.reports.filter(r=>r.id!==report.id)];state.loaded=true;$('#portal-dialog').close();const el=$('#report-list');if(el)el.innerHTML=cards();}catch(err){$('#report-error').hidden=false;$('#report-error').textContent=err.message;}finally{state.busy=false;form.querySelectorAll('input,select,button').forEach(x=>x.disabled=false);}},true);
$('#portal-dialog').addEventListener('cancel',e=>{if(state.busy)e.preventDefault();});
window.addEventListener('kspps-staff-role-changed',()=>{state.loaded=false;state.error='';});
window.KsppsReports={page,mount};
})();
